Scripts.OnLeave:
-- Не перекрашиваем активную вкладку (1=Bidding, 2=Boss DKP, 3=Misc DKP, 4=Messages)
local parentName = this:GetParent():GetName();
local tabId = this:GetID();
local isActive = false;
if (parentName == "FrameConfigBidding" and tabId == 1) or
   (parentName == "FrameConfigBossDkp" and tabId == 2) or
   (parentName == "FrameConfigMiscDkp" and tabId == 3) or
   (parentName == "FrameConfigMessage" and tabId == 4) then
	isActive = true;
end
if not isActive then
	getglobal(this:GetName().."Text"):SetTextColor(1, 1, 1);
end
